export type JunitTest = { file: string; name: string; pass: boolean };

const LOAD_ERROR_NAME = "0 tests collected: load error";

const TOKEN =
  /<!--[\s\S]*?-->|<!\[CDATA\[[\s\S]*?\]\]>|<(\/?)([A-Za-z_][\w:.-]*)((?:\s+[\w:.-]+\s*=\s*(?:"[^"]*"|'[^']*'))*)\s*(\/?)>/g;
const ATTR = /([\w:.-]+)\s*=\s*(?:"([^"]*)"|'([^']*)')/g;

function decode(s: string): string {
  return s.replace(/&(#x[0-9a-fA-F]+|#\d+|lt|gt|amp|quot|apos);/g, (m, e: string) => {
    if (e[0] === "#") {
      const code = e[1] === "x" ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10);
      return Number.isFinite(code) && code <= 0x10ffff ? String.fromCodePoint(code) : m;
    }
    return { lt: "<", gt: ">", amp: "&", quot: '"', apos: "'" }[e] ?? m;
  });
}

function attrs(raw: string): Record<string, string> {
  const out: Record<string, string> = {};
  for (const m of raw.matchAll(ATTR)) out[m[1]] = decode(m[2] ?? m[3] ?? "");
  return out;
}

function norm(p: string): string {
  return p.replace(/\\/g, "/").replace(/^(\.\/)+/, "");
}

function sameFile(a: string, b: string): boolean {
  const x = norm(a);
  const y = norm(b);
  return x === y || x.endsWith("/" + y) || y.endsWith("/" + x);
}

type Suite = { name: string; file?: string };
type Case = { file: string; name: string; failed: boolean; skipped: boolean };

export function parseJunit(
  xml: string,
  expectedFiles: string[],
): { tests: JunitTest[]; loadFailures: string[] } {
  const suites: Suite[] = [];
  const cases: Case[] = [];
  let cur: Case | null = null;
  let outerName = "";

  for (const m of xml.matchAll(TOKEN)) {
    const [, closing, tag, rawAttrs, selfClose] = m;
    if (!tag) continue;
    if (tag === "testsuite") {
      if (closing) suites.pop();
      else {
        const a = attrs(rawAttrs);
        if (suites.length === 0) outerName = a.name ?? "";
        if (!selfClose) suites.push({ name: a.name ?? "", file: a.file });
      }
    } else if (tag === "testcase") {
      if (closing) {
        cur = null;
      } else {
        const a = attrs(rawAttrs);
        const suiteFile = [...suites].reverse().find((s) => s.file)?.file;
        const file = a.file ?? suiteFile ?? (suites.length ? suites[0].name : outerName);
        cur = { file, name: a.name ?? "", failed: false, skipped: false };
        cases.push(cur);
        if (selfClose) cur = null;
      }
    } else if (cur && !closing) {
      if (tag === "failure" || tag === "error") cur.failed = true;
      else if (tag === "skipped") cur.skipped = true;
    }
  }

  const tests: JunitTest[] = cases
    .filter((c) => !c.skipped)
    .map((c) => ({ file: c.file, name: c.name, pass: !c.failed }));

  const loadFailures: string[] = [];
  for (const f of expectedFiles) {
    if (cases.some((c) => sameFile(c.file, f))) continue;
    loadFailures.push(f);
    tests.push({ file: f, name: LOAD_ERROR_NAME, pass: false });
  }
  return { tests, loadFailures };
}

import { describe, expect, test } from "bun:test";
import { parseJunit } from "../src/grade/junit";

describe("parseJunit", () => {
  test("pass, fail, error, skipped; file from testcase, suite attr, suite name", () => {
    const xml = `<?xml version="1.0"?>
<testsuites>
  <testsuite name="tests/a.test.ts" tests="3">
    <testcase name="ok" classname="x"/>
    <testcase name="bad"><failure message="no">boom &amp; &lt;x&gt;</failure></testcase>
    <testcase name="skip"><skipped/></testcase>
  </testsuite>
  <testsuite name="outer" file="tests/b.test.ts">
    <testsuite name="inner describe">
      <testcase name="nested"/>
    </testsuite>
    <testcase name="err" file="tests/c.test.ts"><error type="E"/></testcase>
  </testsuite>
</testsuites>`;
    const r = parseJunit(xml, ["tests/a.test.ts", "tests/b.test.ts", "tests/c.test.ts"]);
    expect(r.loadFailures).toEqual([]);
    expect(r.tests).toEqual([
      { file: "tests/a.test.ts", name: "ok", pass: true },
      { file: "tests/a.test.ts", name: "bad", pass: false },
      { file: "tests/b.test.ts", name: "nested", pass: true },
      { file: "tests/c.test.ts", name: "err", pass: false },
    ]);
  });

  test("expected file with zero testcases gets a synthetic failure", () => {
    const xml = `<testsuites><testsuite name="tests/a.test.ts"><testcase name="ok"/></testsuite>
<testsuite name="tests/empty.test.ts" tests="0"></testsuite></testsuites>`;
    const r = parseJunit(xml, ["./tests/a.test.ts", "tests/empty.test.ts", "tests/missing.test.ts"]);
    expect(r.loadFailures).toEqual(["tests/empty.test.ts", "tests/missing.test.ts"]);
    expect(r.tests.filter((t) => !t.pass)).toEqual([
      { file: "tests/empty.test.ts", name: "0 tests collected: load error", pass: false },
      { file: "tests/missing.test.ts", name: "0 tests collected: load error", pass: false },
    ]);
  });

  test("empty or non-XML input marks every expected file as a load failure", () => {
    expect(parseJunit("", ["x.test.ts"]).loadFailures).toEqual(["x.test.ts"]);
  });

  test("tags inside CDATA and comments are ignored; attributes decoded", () => {
    const xml = `<testsuite name="a.test.ts"><!-- <testcase name="ghost"/> -->
<testcase name="q &quot;1&quot;"><system-out><![CDATA[<testcase name="x"><failure/></testcase>]]></system-out></testcase></testsuite>`;
    const r = parseJunit(xml, ["a.test.ts"]);
    expect(r.tests).toEqual([{ file: "a.test.ts", name: 'q "1"', pass: true }]);
  });
});

